import time
from functools import wraps

def throttle(interval):
    """
    A decorator that throttles a function so it runs no more often than every `interval` seconds.

    Example:
        @throttle(60)
        def my_function():
            ...
    """
    last_call = {}

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            now = time.monotonic()
            last = last_call.get(func, 0)
            if now - last >= interval:
                result = func(*args, **kwargs)
                last_call[func] = now
                return result
            else:
                # Function is throttled
                return None  # or raise a throttling exception
        return wrapper
    return decorator

# Specific one-minute throttling decorator
one_minute_throttle = throttle(60)

@throttle
def my_function():
    print(f"Function called at {time.ctime()}")

@throttle(60)
def my_job():
