def column_stats(table):
    from collections import Counter

    if not table or not table[0]:
        raise ValueError("Input table must contain at least one row (header) and one column.")

    headers = table[0]
    data_rows = table[1:]

    result = {}

    for col_idx, col_name in enumerate(headers):
        try:
            column_data = [float(row[col_idx]) for row in data_rows]
        except ValueError as e:
            raise ValueError(f"Error converting values in column '{col_name}': {e}") from e

        n = len(column_data)
        if n == 0:
            raise ValueError(f"Column '{col_name}' has no data.")

        # 1. Compute mean
        mean = sum(column_data) / n

        # 2. Compute median
        sorted_data = sorted(column_data)
        if n % 2 == 1:
            median = sorted_data[n // 2]
        else:
            median = (sorted_data[n // 2 - 1] + sorted_data[n // 2]) / 2

        # 3. Compute mode
        counter = Counter(column_data)
        mode = counter.most_common(1)[0][0]

        # 4. Compute population variance
        variance = sum((x - mean) ** 2 for x in column_data) / n

        result[col_name] = {
            'mean': mean,
            'median': median,
            'mode': mode,
            'variance': variance
        }

    return result

