def column_stats(table):
    if not table or not isinstance(table, list):
        raise ValueError("The input must be a non-empty table (list of lists).")

    if len(table) < 2:
        raise ValueError("The table must contain at least one row of data in addition to the header.")

    # Extract headers and data rows
    headers = table[0]
    data_rows = table[1:]

    if not all(len(row) == len(headers) for row in data_rows):
        raise ValueError("All rows must have the same number of columns as the header.")

    results = {}

    for col_index in range(len(headers)):
        column_name = headers[col_index]
        column_data = [row[col_index] for row in data_rows]
        n = len(column_data)

        # --- Mean ---
        mean_val = sum(column_data) / n

        # --- Median ---
        sorted_data = sorted(column_data)
        if n % 2 == 1:
            median_val = sorted_data[n // 2]
        else:
            median_val = (sorted_data[n // 2 - 1] + sorted_data[n // 2]) / 2

        # --- Mode ---
        unique_elements = []
        for val in column_data:
            if val not in unique_elements:
                unique_elements.append(val)

        freq = {}
        for val in column_data:
            if val in freq:
                freq[val] += 1
            else:
                freq[val] = 1

        max_freq = max(freq.values())
        mode_candidates = [val for val in unique_elements if freq[val] == max_freq]
        mode_val = mode_candidates[0]  # Select the first element with max frequency

        # --- Variance (population variance) ---
        variance_val = sum((x - mean_val)**2 for x in column_data) / n

        # Store results for this column
        results[column_name] = {
            'mean': mean_val,
            'median': median_val,
            'mode': mode_val,
            'variance': variance_val
        }

    return results

