import os
import time
import subprocess

def watch_file(args):
    file_path = args.file
    command = args.command
    interval = getattr(args, 'interval', 1)

    if not os.path.exists(file_path):
        print(f"File not found: {file_path}")
        return

    try:
        last_mtime = os.path.getmtime(file_path)
    except OSError as e:
        print(f"Error accessing file: {e}")
        return

    print(f"Watching {file_path} for changes...")
    try:
        while True:
            time.sleep(interval)

            if not os.path.exists(file_path):
                print(f"File {file_path} not found. Waiting...")
                continue

            try:
                current_mtime = os.path.getmtime(file_path)
            except OSError as e:
                print(f"Error accessing file: {e}")
                continue

            if current_mtime != last_mtime:
                last_mtime = current_mtime
                print(f"File modified. Running: {command}")
                subprocess.run(command, shell=True)
    except KeyboardInterrupt:
        print("\nStopped watching.")

import os
import time
import subprocess
from . import utils


def watch_file(args):
    file_path = args.file
    command = args.command
    interval = args.interval

    if not os.path.isfile(file_path):
        utils.fatal_error(f"'{file_path}' is not a valid file.")

    try:
        last_mtime = os.path.getmtime(file_path)
    except OSError as e:
        utils.fatal_error(f"Error getting initial modification time: {e}")

    print(f"Watching {file_path} for changes (interval: {interval}s)...\n")

    try:
        while True:
            time.sleep(interval)
            try:
                current_mtime = os.path.getmtime(file_path)
            except OSError as e:
                utils.fatal_error(f"Error accessing {file_path}: {e}")

            if current_mtime != last_mtime:
                print(f"\n[Change detected in {file_path} at {time.ctime()}]")
                print(f"Executing command: {command}")

                try:
                    subprocess.run(command, shell=True, check=True)
                except subprocess.CalledProcessError as e:
                    print(f"Command failed with exit code {e.returncode}.")
                except Exception as e:
                    print(f"Command execution failed: {e}")

                last_mtime = current_mtime  # Update for next check

    except KeyboardInterrupt:
        print("\nWatcher stopped by user.")

