import sys

def get_neighbors(point_index, points, radius):
    x1, y1 = points[point_index]
    radius_sq = radius * radius
    neighbors = []
    for j in range(len(points)):
        x2, y2 = points[j]
        dx = x1 - x2
        dy = y1 - y2
        distance_sq = dx * dx + dy * dy
        if distance_sq <= radius_sq:
            neighbors.append(j)
    return neighbors

def main():
    lines = [line.strip() for line in sys.stdin if line.strip()]
    if not lines:
        return

    # Parse radius and minimum number of samples from the first line
    first_line = lines[0].split()
    if len(first_line) < 2:
        return

    try:
        radius = float(first_line[0])
        min_samples = int(first_line[1])

        # Parse all the 2D points from the remaining lines
        points = []
        for line in lines[1:]:
            coords = list(map(float, line.split()))
            if len(coords) != 2:
                continue  # skip invalid lines (if any)
            points.append(coords)

        n = len(points)
        if n == 0:
            return

        # Initialization
        visited = [False] * n
        cluster_assignments = [-1] * n
        cluster_id = 0

        # DBSCAN clustering algorithm
        for i in range(n):
            if not visited[i]:
                neighbors = get_neighbors(i, points, radius)
                visited[i] = True

                if len(neighbors) < min_samples:
                    cluster_assignments[i] = -1
                else:
                    cluster_assignments[i] = cluster_id
                    queue = deque([i])
                    cluster_id += 1

                    while queue:
                        current_idx = queue.popleft()
                        current_neighbors = get_neighbors(current_idx, points, radius)

                        for neighbor_idx in current_neighbors:
                            if not visited[neighbor_idx]:
                                visited[neighbor_idx] = True
                                cluster_assignments[neighbor_idx] = cluster_id - 1
                                neighbor_neighbors = get_neighbors(neighbor_idx, points, radius)
                                if len(neighbor_neighbors) >= min_samples:
                                    queue.append(neighbor_idx)

        # Output cluster assignments
        for assignment in cluster_assignments:
            print(assignment)

    except (ValueError, IndexError, TypeError):
        # In case of parsing or type errors
        print("-1", file=sys.stderr)
        return

if __name__ == "__main__":
    main()

