from urllib.request import urlopen
from toolbox.utils import is_url

def get_html_content(input_path):
    """
    Fetch HTML content from URL or local file.
    """
    if is_url(input_path):
        with urlopen(input_path) as response:
            content_type = response.info().get_content_type()
            if content_type != 'text/html':
                raise ValueError(f"URL does not point to HTML content: {input_path}")
            encoding = response.info().get_content_charset('utf-8')
            return response.read().decode(encoding)
    else:
        with open(input_path, 'r', encoding='utf-8') as f:
            return f.read()

class LinkExtractor(HTMLParser):
    """
    HTML parser to extract all `href` values from <a> tags.
    """
    def __init__(self):
        super().__init__()
        self.links = []

    def handle_starttag(self, tag, attrs):
        if tag.lower() == 'a':
            for attr, value in attrs:
                if attr.lower() == 'href':
                    self.links.append(value)
                    break  # Only take the first href per tag

def extract_links(args):
    """
    CLI task to extract and print links.
    """
    input_path = args.input
    html = get_html_content(input_path)
    extractor = LinkExtractor()
    extractor.feed(html)
    return extractor.links

