def split_sentences_and_tokenize(
    text: str,
) -> list[list[str]]:
    """Split a paragraph into sentences, and tokenize each sentence into words.

    Returns a list of lists, each containing the words of a sentence.
    """
    sentences = re.split(r'(?<=[.!?])\s+', text)
    sentences = [s for s in sentences if s]  # Filter out empty strings
    return [sentence.split() for sentence in sentences]

