import sys
import math

def main():
    n = int(sys.stdin.readline())
    entries = []
    groups = {}

    for _ in range(n):
        line = sys.stdin.readline().strip()
        parts = line.split()
        group = parts[0]
        value = float(parts[1])
        entries.append((group, value))
        if group not in groups:
            groups[group] = []
        groups[group].append(value)

    group_stats = {}
    for group in groups:
        values = groups[group]
        mean = sum(values) / len(values)
        sum_sq_diff = 0.0
        for v in values:
            sum_sq_diff += (v - mean) ** 2
        variance = sum_sq_diff / len(values)
        std = math.sqrt(variance)
        group_stats[group] = (mean, std)

    for group, val in entries:
        mean, std = group_stats[group]
        if std == 0.0:
            print("0.0000")
        else:
            z = (val - mean) / std
            rounded = round(z, 4)
            print("{0:.4f}".format(rounded))

