    main()

function throttle(func) {
  let lastExecutionTime = 0;
  const cooldown = 60000; // 60 seconds in milliseconds

  return function(...args) {
    const now = Date.now();

    // If cooldown period has passed since the last execution, call the function
    if (now - lastExecutionTime >= cooldown) {
      func.apply(this, args);
      lastExecutionTime = now; // Reset the timer
    }
  };
}

