function throttle(func) {
  let lastExecTime = -Infinity; // Ensures first call is allowed immediately
  const cooldown = 60000;       // 1 minute

  return function throttled(...args) {
    const now = Date.now();

    if (now - lastExecTime >= cooldown) {
      func.apply(this, args); // Apply originated context and preserved arguments
      lastExecTime = now;     // Update the time of the last execution
    }
  };
}

