function throttle(func) {
  let lastExecutionTime = -Infinity; // Ensures the first call is always allowed

  return function(...args) {
    const now = Date.now();

    // Only run if at least 60 seconds have passed since the last execution
    if (now - lastExecutionTime >= 60000) {
      func.apply(this, args); // Maintain context and forward arguments
      lastExecutionTime = now; // Record the time of invocation
    }
    // Otherwise, silently ignore the call
  };
}

