import time

def throttle(func):
    last_time = 0  # Initially set to 0, which allows the first call immediately

    def wrapper(*args, **kwargs):
        nonlocal last_time
        current_time = time.time()

        if current_time - last_time >= 60:
            func(*args, **kwargs)
            last_time = current_time  # Update the timestamp of the last valid invocation

    return wrapper

