from datetime import datetime
from typing import List

def bucket_by_hour(args):
    with open(args.input, 'r', encoding='utf-8') as f:
        lines = f.readlines()

    timestamps = []

    for line in lines:
        line = line.strip()
        if not line:
            continue

        try:
            dt = datetime.strptime(line, args.format)
        except ValueError as e:
            raise ValueError(f"Failed to parse timestamp: {line}") from e

        if dt.tzinfo is None:
            raise ValueError(f"Timestamp must include timezone information. Got: {line}")

        timestamps.append(dt)

    # Grouping by local hour, regardless of date
    grouped = {}

    for dt in timestamps:
        hour_key = dt.hour
        if hour_key not in grouped:
            grouped[hour_key] = []
        grouped[hour_key].append(dt)

    # Format output
    out_format = args.output_format or args.format

    for hour in sorted(grouped.keys()):
        start_time = f"{hour:02d}:00"
        end_time = f"{(hour + 1) % 24:02d}:00"
        print(f"{start_time}-{end_time} (Total: {len(grouped[hour])}):")
        for ts in grouped[hour]:
            print(f"  {ts.strftime(out_format)}")
        print()  # Blank line between groups

