import click
from datetime import datetime
from collections import defaultdict
from zoneinfo import ZoneInfo


@click.command()
@click.argument('input_file', type=click.File('r'), default='-')
@click.option('--date-format', default=None, help='Format string for parsing dates (e.g., "%Y-%m-%d %H:%M:%S")')
@click.option('--timezone', default=None, help='Timezone to apply to naive timestamps (e.g., UTC, Europe/London)')
def bucket_by_hour(input_file, date_format, timezone):
    """
    Group timestamps by the local hour they fall into.
    """
    timestamps = []

    for line in input_file:
        line = line.strip()
        if not line:
            continue

        try:
            if date_format:
                dt = datetime.strptime(line, date_format)
            else:
                try:
                    dt = datetime.fromisoformat(line)
                except ValueError:
                    click.echo(f"Warning: Could not parse ISO date in line: {line}")
                    continue
        except ValueError as e:
            click.echo(f"Error parsing date in line: {line} - {e}")
            continue

        # Handle timezone conversion for naive datetime
        if dt.tzinfo is None and timezone:
            try:
                tz = ZoneInfo(timezone)
                dt = dt.replace(tzinfo=tz)
            except Exception as e:
                click.echo(f"Invalid timezone: {timezone} - {e}")
                return

        timestamps.append(dt)

    # Group by hour
    hourly_buckets = defaultdict(list)
    for dt in timestamps:
        hourly_buckets[dt.hour].append(dt)

    # Output the results
    for hour in sorted(hourly_buckets.keys()):
        click.echo(f"\n-- Hour {hour}:00 --")
        for dt in hourly_buckets[hour]:
            # Output in ISO format if possible, or naive fallback
            click.echo(dt.strftime("%Y-%m-%d %H:%M:%S") +
                       (f" {dt.tzinfo}" if dt.tzinfo else ""))

