def extract_links(
    source: str | Path,
) -> list[str]:
    """Extract all hyperlink URLs from HTML content or an HTML file.

    If the source is a path to an existing file, reads and parses it.
    Otherwise, treats the source as raw HTML content.

    Returns a list of href values from <a> tags.
    """
    # Determine if source is a file path (either Path object or string path)
    if isinstance(source, Path):
        html_content = read_text(source)
    elif isinstance(source, str):
        path = Path(source)
        if path.is_file():
            html_content = read_text(path)
        else:
            html_content = source
    else:
        raise TypeError(f"Unexpected source type: {type(source)}")

    # Parse HTML to extract links
    class LinkExtractor(HTMLParser):
        def __init__(self):
            super().__init__()
            self.links = []

        def handle_starttag(self, tag, attrs):
            if tag.lower() == "a":
                attrs_dict = dict(attrs)
                href = attrs_dict.get("href")
                if href:
                    self.links.append(href)

    parser = LinkExtractor()
    parser.feed(html_content)
    return parser.links

