import sys

def prime_factors(n):
    """Calculate the list of prime factors of a positive integer greater than 1."""
    factors = []
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors.append(d)
            n //= d
        d += 1
    if n > 1:
        factors.append(n)
    return factors

