@app.post("/analyze", status_code=200)
async def analyze_file(file: UploadFile = File(...)):
    from fastapi import HTTPException

    # Check for supported file types
    if not file.filename.lower().endswith((".csv", ".xls", ".xlsx")):
        raise HTTPException(
            status_code=400,
            detail="Unsupported file type. Please upload a CSV or Excel (.xls/.xlsx) file."
        )

    # Read uploaded file content
    try:
        contents = await file.read()
        if file.filename.lower().endswith(".csv"):
            df = pd.read_csv(io.BytesIO(contents))
        else:
            df = pd.read_excel(io.BytesIO(contents))
    except Exception as e:
        raise HTTPException(
            status_code=400,
            detail=f"Error parsing file: {str(e)}"
        )

    # Analyze each column and collect results
    analysis_results = {}
    for col in df.columns:
        col_data = df[col]

        # Handle missing or empty data
        if col_data.isna().all():
            analysis_results[col] = {"error": "All values are missing"}
            continue

        stats = {}

        if pd.api.types.is_numeric_dtype(col_data):
            # Compute stats for numeric columns
            stats["mean"] = float(col_data.mean())
            stats["median"] = float(col_data.median())
            stats["variance"] = float(col_data.var())
            mode = col_data.mode(dropna=True)
            stats["mode"] = float(mode.iloc[0]) if not mode.empty else None
        else:
            # For non-numeric, only compute the mode
            mode = col_data.mode(dropna=True)
            stats["mode"] = mode.iloc[0] if not mode.empty else None

        analysis_results[col] = stats

    return {"analysis": analysis_results}

