import typer
from toolbox.tasks import topological_sort
import json

app = typer.Typer()

@app.command()
def topological_sort_command(
    dependencies: str = typer.Option(..., help="JSON string of dependency list as [ (prerequisite, task), ... ]"),
):
    """
    Determine a valid task execution order based on dependency list.
    Example: "[('task2', 'task1'), ('task3', 'task1')]"
    """
    try:
        dep_list = json.loads(dependencies)
        if not isinstance(dep_list, list) or not all(
            isinstance(dep, list) and len(dep) == 2 for dep in dep_list
        ):
            raise ValueError("Dependencies must be a list of two-element lists.")
    except json.JSONDecodeError as e:
        typer.secho(f"Invalid JSON format: {e}", fg=typer.colors.RED)
        raise typer.Abort()
    except ValueError as e:
        typer.secho(f"Invalid dependency structure: {e}", fg=typer.colors.RED)
        raise typer.Abort()

    try:
        order = topological_sort(dep_list)
        typer.echo("Valid execution order:")
        typer.echo(" -> ".join(order))
    except ValueError as e:
        typer.secho(f"Error: {e}", fg=typer.colors.RED)
        raise typer.Abort()

