from collections import defaultdict, deque

def task_order(dependencies):
    if not dependencies:
        return []

    # Build the graph and in-degree count
    graph = defaultdict(list)
    in_degree = defaultdict(int)
    nodes = set()

    for prereq, task in dependencies:
        nodes.add(prereq)
        nodes.add(task)
        graph[prereq].append(task)
        in_degree[task] += 1  # Increment in-degree of task

    # Initialize the queue with nodes having in-degree 0
    queue = deque()
    for node in nodes:
        if in_degree[node] == 0:
            queue.append(node)

    top_order = []

    while queue:
        current = queue.popleft()
        top_order.append(current)

        for neighbor in graph[current]:
            in_degree[neighbor] -= 1  # Reduce in-degree of each neighbor
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # If top_order includes all nodes, no cycles, otherwise there's a cycle
    if len(top_order) != len(nodes):
        return []  # Indicates a cycle

    return top_order

