from collections import defaultdict

def task_order(dependencies):
    # Step 1: Build graph and calculate in-degrees
    graph = defaultdict(list)
    in_degree = {}
    nodes = set()

    for u, v in dependencies:
        nodes.add(u)
        nodes.add(v)

    for node in nodes:
        in_degree[node] = 0

    for u, v in dependencies:
        graph[u].append(v)
        in_degree[v] += 1

    # Step 2: Initialize priority queue with nodes having zero in-degree
    heap = []
    for node in nodes:
        if in_degree[node] == 0:
            heapq.heappush(heap, node)

    # Step 3: Process nodes using a priority queue to enforce lexicographical order
    result = []
    while heap:
        current = heapq.heappop(heap)
        result.append(current)
        for neighbor in graph[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    # Step 4: Detect cycles
    if len(result) != len(nodes):
        return "Cycle detected in task dependencies"

    return result

