def decompress_file(data: bytes) -> bytes:
    """Detect and decompress a GZIP or ZIP (with 1 file) from given binary data."""

    if data.startswith(b'\x1f\x8b\x08'):
        # GZIP file
        return gzip.GzipFile(fileobj=io.BytesIO(data)).read()
    elif data.startswith(b'PK\x03\x04'):
        # ZIP file
        with io.BytesIO(data) as buffer:
            with zipfile.ZipFile(buffer) as zf:
                file_name = zf.namelist()[0]
                return zf.read(file_name)
    else:
        raise ValueError("Unsupported archive format.")

def main():
    try:
        # Read all binary input from stdin
        data = sys.stdin.buffer.read()
        if not data:
            print("No input received.", file=sys.stderr)
            return

        # Decompress based on detected type
        result = decompress_file(data)

        # Output decompressed content to stdout
        sys.stdout.buffer.write(result)

    except IndexError:
        print("ZIP archive contains no files.", file=sys.stderr)
    except zipfile.BadZipFile:
        print("Invalid ZIP file format.", file=sys.stderr)
    except ValueError as ve:
        print(str(ve), file=sys.stderr)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)

