import os
import time
import threading

def watch_file(file_path, callback):
    def check_changes():
        try:
            # Get the initial modification time of the file
            last_mtime = os.path.getmtime(file_path)
        except FileNotFoundError:
            print(f"Error: The file {file_path} does not exist.")
            return
        while True:
            try:
                current_mtime = os.path.getmtime(file_path)
                if current_mtime != last_mtime:
                    last_mtime = current_mtime  # Update to the latest modification time
                    # Call the user-provided callback
                    try:
                        callback()
                    except Exception as cb_err:
                        print(f"Callback error: {cb_err}")
            except FileNotFoundError:
                print(f"File {file_path} not found. Stopping watcher.")
                break
            except Exception as ex:
                print(f"An unexpected error occurred: {ex}")
            time.sleep(1)  # Check every 1 second

    # Start a background thread to monitor the file
    thread = threading.Thread(target=check_changes, daemon=True)
    thread.start()

