def count_timestamps_by_hour(
    path: str | Path,
) -> dict[str, int]:
    """Count timestamps per local hour of day.

    Assumes timestamps are in ISO format and in the local timezone.
    Returns a dictionary mapping hour strings ('0' to '23') to counts.
    """
    from datetime import datetime

    hours = {}
    for line in read_text(path).splitlines():
        dt = datetime.fromisoformat(line.strip())
        hour_key = str(dt.hour)
        hours[hour_key] = hours.get(hour_key, 0) + 1
    return hours


