def bucket_timestamps_by_hour(
    path: str | Path,
) -> dict[str, int]:
    """Count timestamps by local hour of day.

    Expects one timestamp per line in ISO format (e.g., 'YYYY-MM-DDTHH:MM:SS' or similar).

    Returns a dictionary with keys as hour strings (e.g., '15') and values as counts.
    """
    from datetime import datetime

    timestamps = read_text(path).splitlines()
    counts = {}

    for ts in timestamps:
        ts = ts.strip()
        if not ts:
            continue
        try:
            dt = datetime.fromisoformat(ts)
        except ValueError:
            continue  # Skips malformed lines
        hour = str(dt.hour)
        counts[hour] = counts.get(hour, 0) + 1

    return counts

