#'
#' @param df A data frame containing both numeric and non-numeric (e.g., character, factor) columns.
#' @return A new data frame where numeric columns are standardized (mean = 0, sd = 1).
#'         Non-numeric columns remain unchanged.
standardize <- function(df) {
  for (col in names(df)) {
    if (is.numeric(df[[col]])) {
      # Scale the column using R's base `scale()` function:
      # - Removes mean (centers the data to zero)
      # - Divides by standard deviation (scales to unit variance).
