import time

def throttle(seconds):
    def decorator(func):
        last_run = 0.0  # last time the function was successfully executed
        def wrapper(*args, **kwargs):
            nonlocal last_run
            elapsed = time.time() - last_run
            if elapsed >= seconds:
                result = func(*args, **kwargs)
                last_run = time.time()
                return result
            elif elapsed < 0:  # Just in case the clock goes backwards (very unlikely)
                last_run = time.time()
            return None
        return wrapper
    return decorator

