            if not hasattr(klass, '_throttle_data'):
                klass._throttle_data = {}
            if id(instance) not in klass._throttle_data:
                klass._throttle_data[id(instance)] = -float('inf')

            now = time.time()
            if now - klass._throttle_data[id(instance)] >= self.seconds:
                klass._throttle_data[id(instance)] = now
                return func(instance, *args, **kwargs)
        return wrapped

