def parse_logs(log_lines):
    parsed_data = []

    for line in log_lines:
        line = line.strip()
        if not line:
            continue  # skip empty lines

        # Match lines with the timestamp format and capture the message
        match = re.match(r'^$$(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})$$\s+(.+)$', line)

        if not match:
            continue  # Skip if the line doesn't match the expected format

        timestamp_str, message = match.groups()

        # Try to parse the timestamp
        try:
            timestamp = datetime.strptime(timestamp_str, "%Y-%m-%d %H:%M:%S")
        except ValueError:
            continue  # Skip lines with valid pattern but invalid datetime

        # Successfully parsed — add to the result
        parsed_data.append({
            'timestamp': timestamp,
            'message': message
        })

    return parsed_data

