from typing import List
from collections import Counter

def prime_factors(n: int) -> List[int]:
    """Return the prime factors of a positive integer greater than 1."""
    if n < 2:
        raise ValueError("Input must be a positive integer greater than 1.")

    factors = []
    divisor = 2
    while n > 1:
        while n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        divisor += 1
    return factors

def format_prime_factors(factors: List[int]) -> str:
    """Format a list of prime factors into a human-readable string."""
    counter = Counter(factors)
    parts = []

    for prime in sorted(counter):
        exp = counter[prime]
        if exp > 1:
            parts.append(f"{prime}^{exp}")
        else:
            parts.append(str(prime))

    return " * ".join(parts)

