import heapq

def main():
    # Build the graph from input
    graph = defaultdict(list)
    in_degree = defaultdict(int)
    nodes = set()

    lines = sys.stdin.read().splitlines()

    for line in lines:
        if line.strip() and len(line.split()) == 2:
            task, dependency = line.strip().split()
            nodes.add(task)
            nodes.add(dependency)
            graph[dependency].append(task)
            in_degree[task] += 1

    # Initialize the min-heap with all nodes having in_degree 0
    queue = []
    for node in nodes:
        if in_degree.get(node, 0) == 0:
            heapq.heappush(queue, node)

    sorted_order = []

    while queue:
        u = heapq.heappop(queue)
        sorted_order.append(u)
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(queue, v)

    # Check for cycle
    if len(sorted_order) != len(nodes):
        print("Cycle detected. No valid task order.")
    else:
        print(' '.join(sorted_order))

