def read_archive_contents(archive_path):
    """
    Load the contents of archive files into a dictionary of <filename: content>.

    Only works for text or binary files (directories and symbolic links will be ignored).

    :param archive_path: Path to the archive file
    :return: Dictionary containing filenames and their contents (in bytes)
    """
    supported_extensions = {
        '.zip': 'zip',
        '.tar': 'tar',
        '.tar.gz': 'gzip',
        '.tgz': 'gzip'
    }

    ext = archive_path.lower()
    for ext_key, archive_type in supported_extensions.items():
        if ext.endswith(ext_key):
            if archive_type == 'zip':
                with zipfile.ZipFile(archive_path, 'r') as zip_ref:
                    return {name: zip_ref.read(name) for name in zip_ref.namelist()}
            else:  # tar, tar.gz, tgz
                with tarfile.open(archive_path, 'r:*') as tar_ref:
                    files = {}
                    for member in tar_ref.getmembers():
                        if not member.isdir():  # Skip directories
                            f = tar_ref.extractfile(member)
                            if f:
                                files[member.name] = f.read()
                    return files

    raise ValueError(f"Archive type not supported: {archive_path}")

def read_zip_in_memory(zip_path):
    with zipfile.ZipFile(zip_path, 'r') as zip_ref:
        return {name: zip_ref.read(name) for name in zip_ref.namelist()}

def read_tar_in_memory(tar_path):
    contents = {}
    with tarfile.open(tar_path, 'r:*') as tar_ref:
        for member in tar_ref:
            if member.isfile():
                contents[member.name] = tar_ref.extractfile(member).read()
    return contents

