    - Dict[str, bytes]: Dictionary of filenames mapped to their content (in bytes) if return_data=True.
    - Raises an error if the file or format is not supported.
    """

    archive_path = Path(archive_path)
    if not archive_path.exists():
        raise FileNotFoundError(f"The archive does not exist at: '{archive_path}'")

    suffix = archive_path.suffix.lower()

    if return_data:
        result = {}
    else:
        result = []

    try:
        if suffix == '.zip':
            with zipfile.ZipFile(archive_path, 'r') as zip_ref:
                for info in zip_ref.infolist():
                    if not info.is_dir():
                        relative_name = info.filename
                        if return_data:
                            result[relative_name] = zip_ref.read(relative_name)
                        else:
                            result.append(relative_name)

        elif suffix in ('.tar', '.gz'):
            # Use compression mode based on file extension
            mode = 'r:*'
            with tarfile.open(archive_path, mode) as tar_ref:
                for member in tar_ref:
                    if member.isfile():
                        relative_name = member.name
                        if return_data:
                            with tar_ref.extractfile(member) as file:
                                result[relative_name] = file.read()
                        else:
                            result.append(relative_name)

        else:
            raise ValueError(f"Unsupported archive type: '{suffix}'")

    except Exception as e:
        raise RuntimeError(f"An error occurred during archive extraction: {e}")

    return result

