    archive_path: str | Path,
    out_path: str | Path,
) -> None:
    """Extract an archive and write a list of its files to a file.

    Files are listed with their paths relative to the extraction directory.
    """
    archive = Path(archive_path)
    extract_dir = archive.parent / archive.stem
    shutil.unpack_archive(str(archive), extract_dir)
    files = []
    for path in extract_dir.rglob('*'):
        if path.is_file():
            files.append(str(path.relative_to(extract_dir)))
    write_text(out_path, '\n'.join(files) + '\n')

