    archive_path: str | Path,
    dest_dir: str | Path,
) -> list[str]:
    """Extract an archive file to the destination directory and list its contents.

    Returns the list of extracted file paths.
    """
    shutil.unpack_archive(str(archive_path), str(dest_dir))

    files = []
    for path in Path(dest_dir).rglob("*"):
        if path.is_file():
