def determine_execution_order(
    dependencies: list[tuple[str, str]],
) -> list[str]:
    """Determine a valid execution order from task dependencies.

    Dependencies are pairs of (task, prerequisite), meaning `task` depends on `prerequisite`.

    Returns the order as a list of task names.

    Raises:
        ValueError: If there is a cycle in the dependencies.
    """
    tasks = set()
    for task, prerequisite in dependencies:
        tasks.add(task)
        tasks.add(prerequisite)

    if not tasks:
        return []

    # Build graph and in-degree counts (from Kahn's algorithm)
    graph = defaultdict(list)
    in_degree = {task: 0 for task in tasks}

    for task, prerequisite in dependencies:
        graph[prerequisite].append(task)
        in_degree[task] += 1

    # Start with tasks that have no prerequisites
    queue = deque([task for task in in_degree if in_degree[task] == 0])
    top_order = []

    while queue:
        current = queue.popleft()
        top_order.append(current)
        for dependent in graph[current]:
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                queue.append(dependent)

    if len(top_order) != len(tasks):
        raise ValueError("Cycle detected in dependencies")

    return top_order

try:
