import sys
import math

def main():
    rows = []
    for line in sys.stdin:
        stripped = line.strip()
        if not stripped:
            continue
        rows.append(stripped.split())
    if not rows:
        return

    # Determine which columns are numeric
    num_cols = len(rows[0])
    numeric_cols = []

    for j in range(num_cols):
        is_numeric = True
        for i in range(len(rows)):
            try:
                float(rows[i][j])
            except ValueError:
                is_numeric = False
                break
        if is_numeric:
            numeric_cols.append(j)

    # Calculate means and standard deviations for numeric columns
    col_means = {}
    col_stds = {}

    for j in numeric_cols:
        values = [float(rows[i][j]) for i in range(len(rows))]
        mean = sum(values) / len(values)
        col_means[j] = mean
        variance = sum((x - mean) ** 2 for x in values) / len(values)
        std = math.sqrt(variance)
        if std == 0.0:
            std = 1.0  # Avoid division by zero
        col_stds[j] = std

    # Standardize and output
    for i in range(len(rows)):
        new_row = []
        for j in range(len(rows[i])):
            if j in numeric_cols:
                val = float(rows[i][j])
                mean = col_means[j]
                std = col_stds[j]
                standardized = (val - mean) / std
                new_row.append(f"{standardized:.10g}")
            else:
                new_row.append(rows[i][j])
        print(" ".join(new_row))

if __name__ == "__main__":
    main()
